bg = 4
from collections import deque

def get_components(grid):
    H, W = len(grid), len(grid[0])
    visited = set()
    comps = {}
    for r in range(H):
        for c in range(W):
            if grid[r][c] != bg and (r, c) not in visited:
                color = grid[r][c]
                comp = set()
                q = deque([(r,c)])
                while q:
                    cr, cc = q.popleft()
                    if (cr,cc) in visited: continue
                    visited.add((cr,cc))
                    comp.add((cr,cc))
                    for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr,nc = cr+dr, cc+dc
                        if 0<=nr<H and 0<=nc<W and grid[nr][nc]==color and (nr,nc) not in visited:
                            q.append((nr,nc))
                if color not in comps: comps[color]=[]
                comps[color].append(comp)
    return comps

